231	        internal async Task<User> CreateUserInternalAsync(string name, JellyfinDbContext dbContext)
232	        {
233	            // TODO: Remove after user item data is migrated.
234	            var max = await dbContext.Users.AsQueryable().AnyAsync().ConfigureAwait(false)
235	                ? await dbContext.Users.AsQueryable().Select(u => u.InternalId).MaxAsync().ConfigureAwait(false)
236	                : 0;
237	
238	            var user = new User(
239	                name,
240	                _defaultAuthenticationProvider.GetType().FullName!,
241	                _defaultPasswordResetProvider.GetType().FullName!)
242	            {
243	                InternalId = max + 1
244	            };
245	
246	            user.AddDefaultPermissions();
247	            user.AddDefaultPreferences();
248	
249	            return user;
