288	        /// <inheritdoc/>
289	        public async Task DeleteUserAsync(Guid userId)
290	        {
291	            User? user;
292	            using (await _userLock.LockAsync(userId).ConfigureAwait(false))
293	            {
294	                var dbContext = await _dbProvider.CreateDbContextAsync().ConfigureAwait(false);
295	                await using (dbContext.ConfigureAwait(false))
296	                {
297	                    user = await dbContext.Users
298	                        .Include(u => u.Permissions)
299	                        .FirstOrDefaultAsync(u => u.Id.Equals(userId))
300	                        .ConfigureAwait(false);
301	
302	                    if (user is null)
303	                    {
304	                        throw new ResourceNotFoundException(nameof(userId));
305	                    }
306	
307	                    var userCount = await dbContext.Users.CountAsync().ConfigureAwait(false);
308	                    if (userCount == 1)
309	                    {
310	                        throw new InvalidOperationException(string.Format(
311	                            CultureInfo.InvariantCulture,
312	                            "The user '{0}' cannot be deleted because there must be at least one user in the system.",
313	                            user.Username));
314	                    }
315	
316	                    if (user.HasPermission(PermissionKind.IsAdministrator)
317	                        && await dbContext.Users
318	                            .CountAsync(i => i.Permissions.Any(p => p.Kind == PermissionKind.IsAdministrator && p.Value))
319	                            .ConfigureAwait(false) == 1)
320	                    {
321	                        throw new ArgumentException(
322	                            string.Format(
323	                                CultureInfo.InvariantCulture,
324	                                "The user '{0}' cannot be deleted because there must be at least one admin user in the system.",
325	                                user.Username),
326	                            nameof(userId));
327	                    }
328	
329	                    dbContext.Users.Remove(user);
330	                    await dbContext.SaveChangesAsync().ConfigureAwait(false);
331	                }
332	            }
333	
334	            await _eventManager.PublishAsync(new UserDeletedEventArgs(user)).ConfigureAwait(false);
335	        }
