344	        public async Task ChangePassword(Guid userId, string newPassword)
345	        {
346	            User dbUser = null!;
347	            using (await _userLock.LockAsync(userId).ConfigureAwait(false))
348	            {
349	                var dbContext = await _dbProvider.CreateDbContextAsync().ConfigureAwait(false);
350	                await using (dbContext.ConfigureAwait(false))
351	                {
352	                    dbUser = await UserQuery(dbContext)
353	                        .AsTracking()
354	                        .FirstOrDefaultAsync(u => u.Id == userId)
355	                        .ConfigureAwait(false)
356	                        ?? throw new ResourceNotFoundException(nameof(userId));
357	
358	                    if (dbUser.HasPermission(PermissionKind.IsAdministrator) && string.IsNullOrWhiteSpace(newPassword))
359	                    {
360	                        throw new ArgumentException("Admin user passwords must not be empty", nameof(newPassword));
361	                    }
362	
363	                    await GetAuthenticationProvider(dbUser).ChangePassword(dbUser, newPassword).ConfigureAwait(false);
364	                    await dbContext.SaveChangesAsync().ConfigureAwait(false);
365	                }
366	            }
367	
368	            await _eventManager.PublishAsync(new UserPasswordChangedEventArgs(dbUser)).ConfigureAwait(false);
369	        }
