458	        /// <inheritdoc/>
459	        public async Task<User?> AuthenticateUser(
460	            string username,
461	            string password,
462	            string remoteEndPoint,
463	            bool isUserSession)
464	        {
465	            if (string.IsNullOrWhiteSpace(username))
466	            {
467	                _logger.LogInformation("Authentication request without username has been denied (IP: {IP}).", remoteEndPoint);
468	                throw new ArgumentNullException(nameof(username));
469	            }
470	
471	            bool success;
472	            var user = GetUserByName(username);
473	            using (await _userLock.LockAsync(user?.Id ?? Guid.Empty).ConfigureAwait(false))
474	            {
475	                // Reload the user now that we hold the lock so the RowVersion is current.
476	                // GetUserByName uses AsNoTracking and the snapshot may be stale if another
477	                // write (e.g. a concurrent login) incremented RowVersion after our initial load.
478	                if (user is not null)
479	                {
480	                    user = GetUserById(user.Id) ?? user;
481	                }
482	
483	                var authResult = await AuthenticateLocalUser(username, password, user)
484	                                .ConfigureAwait(false);
485	                var authenticationProvider = authResult.AuthenticationProvider;
486	                success = authResult.Success;
487	
488	                if (user is null)
489	                {
490	                    string updatedUsername = authResult.Username;
491	
492	                    if (success
493	                        && authenticationProvider is not null
494	                        && authenticationProvider is not DefaultAuthenticationProvider)
495	                    {
496	                        // Trust the username returned by the authentication provider
497	                        username = updatedUsername;
498	
499	                        // Search the database for the user again
500	                        // the authentication provider might have created it
501	                        user = GetUserByName(username);
502	
503	                        if (authenticationProvider is IHasNewUserPolicy hasNewUserPolicy && user is not null)
504	                        {
505	                            await UpdatePolicyAsync(user.Id, hasNewUserPolicy.GetNewUserPolicy()).ConfigureAwait(false);
506	                        }
507	                    }
508	                }
509	
510	                if (success && user is not null && authenticationProvider is not null)
511	                {
512	                    var providerId = authenticationProvider.GetType().FullName;
513	
514	                    if (providerId is not null && !string.Equals(providerId, user.AuthenticationProviderId, StringComparison.OrdinalIgnoreCase))
515	                    {
516	                        user.AuthenticationProviderId = providerId;
517	                        await UpdateUserInternalAsync(user).ConfigureAwait(false);
518	                    }
519	                }
520	
521	                if (user is null)
522	                {
523	                    _logger.LogInformation(
524	                        "Authentication request for {UserName} has been denied (IP: {IP}).",
525	                        username,
526	                        remoteEndPoint);
527	                    throw new AuthenticationException("Invalid username or password entered.");
528	                }
529	
530	                if (user.HasPermission(PermissionKind.IsDisabled))
531	                {
532	                    _logger.LogInformation(
533	                        "Authentication request for {UserName} has been denied because this account is currently disabled (IP: {IP}).",
534	                        username,
535	                        remoteEndPoint);
536	                    throw new SecurityException(
537	                        $"The {user.Username} account is currently disabled. Please consult with your administrator.");
538	                }
539	
540	                if (!user.HasPermission(PermissionKind.EnableRemoteAccess) &&
541	                    !_networkManager.IsInLocalNetwork(remoteEndPoint))
542	                {
543	                    _logger.LogInformation(
544	                        "Authentication request for {UserName} forbidden: remote access disabled and user not in local network (IP: {IP}).",
545	                        username,
546	                        remoteEndPoint);
547	                    throw new SecurityException("Forbidden.");
548	                }
549	
550	                if (!user.IsParentalScheduleAllowed())
551	                {
552	                    _logger.LogInformation(
553	                        "Authentication request for {UserName} is not allowed at this time due parental restrictions (IP: {IP}).",
554	                        username,
555	                        remoteEndPoint);
556	                    throw new SecurityException("User is not allowed access at this time.");
557	                }
558	
559	                // Update LastActivityDate and LastLoginDate, then save
560	                if (success)
561	                {
562	                    if (isUserSession)
563	                    {
564	                        user.LastActivityDate = user.LastLoginDate = DateTime.UtcNow;
565	                    }
566	
567	                    user.InvalidLoginAttemptCount = 0;
568	                    await UpdateUserInternalAsync(user).ConfigureAwait(false);
569	                    _logger.LogInformation("Authentication request for {UserName} has succeeded.", user.Username);
570	                }
571	                else
572	                {
573	                    await IncrementInvalidLoginAttemptCount(user).ConfigureAwait(false);
574	                    _logger.LogInformation(
575	                        "Authentication request for {UserName} has been denied (IP: {IP}).",
576	                        user.Username,
577	                        remoteEndPoint);
578	                }
579	            }
