929	                    ? await requiresResolvedUser.Authenticate(username, password, resolvedUser).ConfigureAwait(false)
930	                    : await provider.Authenticate(username, password).ConfigureAwait(false);
931	
932	                if (authenticationResult.Username != username)
933	                {
934	                    _logger.LogDebug("Authentication provider provided updated username {1}", authenticationResult.Username);
935	                    username = authenticationResult.Username;
936	                }
937	
938	                return (username, true);
939	            }
940	            catch (AuthenticationException ex)
941	            {
